import java.nio.*;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;
import com.google.gson.*;
import org.lwjgl.glfw.GLFW;
import org.lwjgl.opengl.*;


/** Replays only declared full command journals. Schema-1/2 snapshots are rejected. */
public final class ParticleReplayGpu extends ModelPopulationGpuValidation {
    static ByteBuffer loadFile(Path path)throws Exception{byte[] raw=Files.readAllBytes(path);var out=org.lwjgl.BufferUtils.createByteBuffer(raw.length);out.put(raw).flip();return out;}
    static ByteBuffer file(Path root,String name)throws Exception{Path path=root.resolve(name).normalize();check(path.getParent().equals(root),"contained journal file");return loadFile(path);}
    static final class Replay implements AutoCloseable {
        final Path root;final JsonObject manifest,resources;final Map<String,Integer> buffers=new LinkedHashMap<>(),masters=new LinkedHashMap<>(),textures=new LinkedHashMap<>(),programs=new LinkedHashMap<>();final Map<String,ByteBuffer> textureSeeds=new HashMap<>();final Map<Integer,Integer> samplers=new HashMap<>();
        final Map<String,String> programLoading=new TreeMap<>();final int timer=GL15.glGenQueries(); java.util.function.Consumer<JsonObject> beforeDispatch=e->{};
        final Map<String,ByteBuffer> payloads=new HashMap<>();
        Replay(Path directory)throws Exception{this(directory,"production");} Replay(Path directory,String backend)throws Exception{
            root=directory.toAbsolutePath().normalize();manifest=JsonParser.parseString(Files.readString(root.resolve("manifest.json"))).getAsJsonObject();check(manifest.get("schema").getAsInt()==3&&manifest.get("kind").getAsString().equals("gpu-command-chain")&&manifest.get("complete").getAsBoolean()&&manifest.get("failure_reason").getAsString().isEmpty(),"complete full-chain journal required");check(manifest.get("storage_bytes").getAsLong()<=(512L<<20),"bounded journal");check(manifest.get("gpu").getAsString().equals(GL11.glGetString(GL11.GL_RENDERER))&&manifest.get("driver").getAsString().equals(GL11.glGetString(GL11.GL_VERSION)),"program binary GPU/driver provenance");
            for(var entry:manifest.getAsJsonObject("sha256").entrySet()){var hash=MessageDigest.getInstance("SHA-256");hash.update(file(root,entry.getKey()));check(HexFormat.of().formatHex(hash.digest()).equals(entry.getValue().getAsString()),"journal checksum "+entry.getKey());}
            resources=manifest.getAsJsonObject("resources"); for(var command:manifest.getAsJsonArray("commands")){var e=command.getAsJsonObject();if(e.has("payload")){String key=e.get("payload").getAsString();payloads.put(key,file(root,key));}}
            for(var entry:resources.entrySet()){var d=entry.getValue().getAsJsonObject();if(!d.get("type").getAsString().equals("buffer"))continue;ByteBuffer seed=file(root,d.get("file").getAsString());check(seed.remaining()==d.get("bytes").getAsInt(),"initial buffer size");int master=ModelPopulationGpuValidation.buffer(seed),working=GL15.glGenBuffers();GL15.glBindBuffer(GL43.GL_SHADER_STORAGE_BUFFER,working);if(seed.hasRemaining()){if(d.get("immutable").getAsBoolean())GL44.glBufferStorage(GL43.GL_SHADER_STORAGE_BUFFER,seed,d.get("storage_flags").getAsInt());else GL15.glBufferData(GL43.GL_SHADER_STORAGE_BUFFER,seed,d.get("usage").getAsInt());}else GL15.glBufferData(GL43.GL_SHADER_STORAGE_BUFFER,0,GL15.GL_DYNAMIC_COPY);buffers.put(entry.getKey(),working);masters.put(entry.getKey(),master);}
            for(var entry:resources.entrySet()){var d=entry.getValue().getAsJsonObject();if(!d.get("type").getAsString().equals("texture"))continue;int texture=GL11.glGenTextures();textures.put(entry.getKey(),texture);if(d.get("target").getAsInt()!=GL31.GL_TEXTURE_BUFFER){ByteBuffer seed=file(root,d.get("file").getAsString());textureSeeds.put(entry.getKey(),seed);uploadTexture(entry.getKey(),true);}}
            for(var entry:manifest.getAsJsonObject("programs").entrySet()){var d=entry.getValue().getAsJsonObject();int program=GL20.glCreateProgram();if(!Boolean.getBoolean("cmi.particle.forceSource"))GL41.glProgramBinary(program,d.get("format").getAsInt(),file(root,d.get("binary").getAsString()));programLoading.put(entry.getKey(),"binary");if(GL20.glGetProgrami(program,GL20.GL_LINK_STATUS)==0){String log=GL20.glGetProgramInfoLog(program);check(GL11.glGetError()!=GL45.GL_CONTEXT_LOST,"GPU context lost loading binary");GL20.glDeleteProgram(program);programLoading.put(entry.getKey(),"captured-source");check(d.has("compute_source"),"unreplayable "+entry.getKey()+": binary rejected and no captured shader source: "+log);program=com.iridium126.createmanaindustry.client.gpu.shader.GpuShaderCompiler.compute("captured source "+entry.getKey(),java.nio.charset.StandardCharsets.UTF_8.decode(file(root,d.get("compute_source").getAsString())).toString());}programs.put(entry.getKey(),program);}check(GL11.glGetError()==0,"journal resource reconstruction");
        }
        int buffer(String key){return key.equals("none")?0:Objects.requireNonNull(buffers.get(key),key);}
        int texture(String key){if(key.equals("none"))return 0;var d=resources.getAsJsonObject(key);int id=textures.get(key);if(d.get("target").getAsInt()==GL31.GL_TEXTURE_BUFFER){GL11.glBindTexture(GL31.GL_TEXTURE_BUFFER,id);int source=buffer(d.get("buffer").getAsString());long bytes=d.get("bytes").getAsLong();if(bytes>0)GL43.glTexBufferRange(GL31.GL_TEXTURE_BUFFER,d.get("format").getAsInt(),source,d.get("offset").getAsLong(),bytes);else GL31.glTexBuffer(GL31.GL_TEXTURE_BUFFER,d.get("format").getAsInt(),source);}return id;}
        void uploadTexture(String key,boolean allocate){var d=resources.getAsJsonObject(key);int target=d.get("target").getAsInt();var size=d.getAsJsonArray("size");GL11.glBindTexture(target,textures.get(key));GL15.glBindBuffer(GL21.GL_PIXEL_UNPACK_BUFFER,0);GL11.glPixelStorei(GL11.GL_UNPACK_ALIGNMENT,1);ByteBuffer data=textureSeeds.get(key).duplicate();if(target==GL12.GL_TEXTURE_3D){if(allocate)GL12.glTexImage3D(target,0,d.get("format").getAsInt(),size.get(0).getAsInt(),size.get(1).getAsInt(),size.get(2).getAsInt(),0,d.get("pixel_format").getAsInt(),d.get("pixel_type").getAsInt(),data);else GL12.glTexSubImage3D(target,0,0,0,0,size.get(0).getAsInt(),size.get(1).getAsInt(),size.get(2).getAsInt(),d.get("pixel_format").getAsInt(),d.get("pixel_type").getAsInt(),data);}else{if(allocate)GL11.glTexImage2D(target,0,d.get("format").getAsInt(),size.get(0).getAsInt(),size.get(1).getAsInt(),0,d.get("pixel_format").getAsInt(),d.get("pixel_type").getAsInt(),data);else GL11.glTexSubImage2D(target,0,0,0,size.get(0).getAsInt(),size.get(1).getAsInt(),d.get("pixel_format").getAsInt(),d.get("pixel_type").getAsInt(),data);}}
        void reset(){GL42.glMemoryBarrier(GL42.GL_ALL_BARRIER_BITS);for(var entry:buffers.entrySet()){var d=resources.getAsJsonObject(entry.getKey());long size=d.get("bytes").getAsLong();GL15.glBindBuffer(GL31.GL_COPY_WRITE_BUFFER,entry.getValue());if(!d.get("immutable").getAsBoolean())GL15.glBufferData(GL31.GL_COPY_WRITE_BUFFER,size,d.get("usage").getAsInt());if(size>0){GL15.glBindBuffer(GL31.GL_COPY_READ_BUFFER,masters.get(entry.getKey()));GL31.glCopyBufferSubData(GL31.GL_COPY_READ_BUFFER,GL31.GL_COPY_WRITE_BUFFER,0,0,size);}}for(String key:textureSeeds.keySet())uploadTexture(key,false);GL42.glMemoryBarrier(GL42.GL_ALL_BARRIER_BITS);}
        static int[] integers(JsonArray values){int[] result=new int[values.size()];for(int i=0;i<result.length;i++)result[i]=values.get(i).getAsInt();return result;}
        static void uniforms(int p,JsonObject values){for(var entry:values.entrySet()){int at=GL20.glGetUniformLocation(p,entry.getKey());if(at<0)continue;var d=entry.getValue().getAsJsonObject();int type=d.get("type").getAsInt();int[] bits=integers(d.getAsJsonArray("value"));if(d.has("float_bits")&&d.get("float_bits").getAsBoolean()){float[] data=new float[bits.length];for(int i=0;i<bits.length;i++)data[i]=Float.intBitsToFloat(bits[i]);switch(type){case GL20.GL_FLOAT_MAT2->GL41.glProgramUniformMatrix2fv(p,at,false,data);case GL20.GL_FLOAT_MAT3->GL41.glProgramUniformMatrix3fv(p,at,false,data);case GL20.GL_FLOAT_MAT4->GL41.glProgramUniformMatrix4fv(p,at,false,data);default->{switch(data.length){case 1->GL41.glProgramUniform1fv(p,at,data);case 2->GL41.glProgramUniform2fv(p,at,data);case 3->GL41.glProgramUniform3fv(p,at,data);case 4->GL41.glProgramUniform4fv(p,at,data);default->throw new IllegalStateException("uniform float shape");}}}}else{boolean unsigned=type==GL11.GL_UNSIGNED_INT||type>=GL30.GL_UNSIGNED_INT_VEC2&&type<=GL30.GL_UNSIGNED_INT_VEC4;if(unsigned)switch(bits.length){case 1->GL41.glProgramUniform1uiv(p,at,bits);case 2->GL41.glProgramUniform2uiv(p,at,bits);case 3->GL41.glProgramUniform3uiv(p,at,bits);case 4->GL41.glProgramUniform4uiv(p,at,bits);default->throw new IllegalStateException("uniform uint shape");}else switch(bits.length){case 1->GL41.glProgramUniform1iv(p,at,bits);case 2->GL41.glProgramUniform2iv(p,at,bits);case 3->GL41.glProgramUniform3iv(p,at,bits);case 4->GL41.glProgramUniform4iv(p,at,bits);default->throw new IllegalStateException("uniform int shape");}}}}
        int inputs(JsonObject state){int p=programs.get(state.get("program").getAsString());GL20.glUseProgram(p);uniforms(p,state.getAsJsonObject("uniforms"));for(var entry:state.getAsJsonObject("ssbo").entrySet()){var d=entry.getValue().getAsJsonObject();int slot=Integer.parseInt(entry.getKey()),id=buffer(d.get("buffer").getAsString());if(id!=0&&d.get("bytes").getAsLong()>0)GL30.glBindBufferRange(GL43.GL_SHADER_STORAGE_BUFFER,slot,id,d.get("offset").getAsLong(),d.get("bytes").getAsLong());else GL30.glBindBufferBase(GL43.GL_SHADER_STORAGE_BUFFER,slot,id);}
            for(var entry:state.getAsJsonObject("images").entrySet()){var d=entry.getValue().getAsJsonObject();GL42.glBindImageTexture(Integer.parseInt(entry.getKey()),texture(d.get("texture").getAsString()),0,false,0,d.get("access").getAsInt(),d.get("format").getAsInt());}
            for(var entry:state.getAsJsonObject("samplers").entrySet()){int unit=Integer.parseInt(entry.getKey());var d=entry.getValue().getAsJsonObject();GL13.glActiveTexture(GL13.GL_TEXTURE0+unit);GL11.glBindTexture(d.get("target").getAsInt(),texture(d.get("texture").getAsString()));var parameters=d.getAsJsonObject("state");if(parameters.size()==0){GL33.glBindSampler(unit,0);continue;}int sampler=samplers.computeIfAbsent(unit,key->GL33.glGenSamplers());for(var item:parameters.entrySet()){int parameter=Integer.parseInt(item.getKey());if(item.getValue().isJsonArray()){float[] border=new float[4];for(int i=0;i<4;i++)border[i]=item.getValue().getAsJsonArray().get(i).getAsFloat();GL33.glSamplerParameterfv(sampler,parameter,border);}else if(parameter==GL12.GL_TEXTURE_MIN_LOD||parameter==GL12.GL_TEXTURE_MAX_LOD||parameter==GL14.GL_TEXTURE_LOD_BIAS)GL33.glSamplerParameterf(sampler,parameter,item.getValue().getAsFloat());else GL33.glSamplerParameteri(sampler,parameter,item.getValue().getAsInt());}GL33.glBindSampler(unit,sampler);}return p;
        }
        double[] run()throws Exception{reset();long start=System.nanoTime();GL15.glBeginQuery(GL33.GL_TIME_ELAPSED,timer);try{for(var value:manifest.getAsJsonArray("commands")){var e=value.getAsJsonObject();String op=e.get("op").getAsString();var a=e.getAsJsonArray("args");ByteBuffer payload=e.has("payload")?payloads.get(e.get("payload").getAsString()).duplicate():null;switch(op){case "allocate"->{GL15.glBindBuffer(GL43.GL_SHADER_STORAGE_BUFFER,buffer(e.get("buffer").getAsString()));GL15.glBufferData(GL43.GL_SHADER_STORAGE_BUFFER,a.get(1).getAsLong(),a.get(2).getAsInt());}case "allocate-upload"->{GL15.glBindBuffer(GL43.GL_SHADER_STORAGE_BUFFER,buffer(e.get("buffer").getAsString()));GL15.glBufferData(GL43.GL_SHADER_STORAGE_BUFFER,payload,a.get(2).getAsInt());}case "upload"->{GL15.glBindBuffer(GL43.GL_SHADER_STORAGE_BUFFER,buffer(e.get("buffer").getAsString()));GL15.glBufferSubData(GL43.GL_SHADER_STORAGE_BUFFER,a.get(1).getAsLong(),payload);}case "copy"->{GL15.glBindBuffer(GL31.GL_COPY_READ_BUFFER,buffer(e.get("read").getAsString()));GL15.glBindBuffer(GL31.GL_COPY_WRITE_BUFFER,buffer(e.get("write").getAsString()));GL31.glCopyBufferSubData(GL31.GL_COPY_READ_BUFFER,GL31.GL_COPY_WRITE_BUFFER,a.get(2).getAsLong(),a.get(3).getAsLong(),a.get(4).getAsLong());}case "clear"->{GL15.glBindBuffer(GL43.GL_SHADER_STORAGE_BUFFER,buffer(e.get("buffer").getAsString()));GL43.glClearBufferData(GL43.GL_SHADER_STORAGE_BUFFER,a.get(1).getAsInt(),a.get(2).getAsInt(),a.get(3).getAsInt(),payload);}case "clear-range"->{GL15.glBindBuffer(GL43.GL_SHADER_STORAGE_BUFFER,buffer(e.get("buffer").getAsString()));GL43.glClearBufferSubData(GL43.GL_SHADER_STORAGE_BUFFER,a.get(1).getAsInt(),a.get(2).getAsLong(),a.get(3).getAsLong(),a.get(4).getAsInt(),a.get(5).getAsInt(),payload);}case "barrier"->GL42.glMemoryBarrier((int)a.get(0).getAsLong());case "texture-upload"->{if(e.has("unpack"))for(var item:e.getAsJsonObject("unpack").entrySet())GL11.glPixelStorei(Integer.parseInt(item.getKey()),item.getValue().getAsInt());int target=a.get(0).getAsInt();GL11.glBindTexture(target,texture(e.get("texture").getAsString()));GL15.glBindBuffer(GL21.GL_PIXEL_UNPACK_BUFFER,0);GL12.glTexSubImage3D(target,a.get(1).getAsInt(),a.get(2).getAsInt(),a.get(3).getAsInt(),a.get(4).getAsInt(),a.get(5).getAsInt(),a.get(6).getAsInt(),a.get(7).getAsInt(),a.get(8).getAsInt(),a.get(9).getAsInt(),payload);}case "dispatch"->{beforeDispatch.accept(e);inputs(e.getAsJsonObject("inputs"));GL43.glDispatchCompute(a.get(0).getAsInt(),a.get(1).getAsInt(),a.get(2).getAsInt());}case "dispatch-indirect"->{beforeDispatch.accept(e);inputs(e.getAsJsonObject("inputs"));GL15.glBindBuffer(GL43.GL_DISPATCH_INDIRECT_BUFFER,buffer(e.get("indirect").getAsString()));GL43.glDispatchComputeIndirect(a.get(0).getAsLong());}default->throw new IllegalStateException("unknown command "+op);}}}finally{GL15.glEndQuery(GL33.GL_TIME_ELAPSED);}double cpu=(System.nanoTime()-start)/1e6,gpu=GL33.glGetQueryObjectui64(timer,GL15.GL_QUERY_RESULT)/1e6;check(GL11.glGetError()==0,"full journal replay GL state");return new double[]{gpu,cpu};}
        Map<String,String> hashes()throws Exception{var out=new TreeMap<String,String>();for(var entry:buffers.entrySet()){GL15.glBindBuffer(GL43.GL_SHADER_STORAGE_BUFFER,entry.getValue());int count=GL15.glGetBufferParameteri(GL43.GL_SHADER_STORAGE_BUFFER,GL15.GL_BUFFER_SIZE);var hash=MessageDigest.getInstance("SHA-256");hash.update(read(entry.getValue(),count));out.put(entry.getKey(),HexFormat.of().formatHex(hash.digest()));}return out;}
        @Override public void close(){for(int p:programs.values())deleteProgram(p);for(int id:textures.values())GL11.glDeleteTextures(id);for(int id:samplers.values())GL33.glDeleteSamplers(id);for(int id:buffers.values())GL15.glDeleteBuffers(id);for(int id:masters.values())GL15.glDeleteBuffers(id);GL15.glDeleteQueries(timer);}
    }
    static void contextForCapture(Path capture)throws Exception{var m=JsonParser.parseString(Files.readString(capture.resolve("manifest.json"))).getAsJsonObject();var match=java.util.regex.Pattern.compile("^(\\d+)\\.(\\d+)\\.").matcher(m.get("driver").getAsString());check(match.find(),"captured GL version");if(m.has("gl_context_profile_mask"))GLFW.glfwWindowHint(GLFW.GLFW_OPENGL_PROFILE,(m.get("gl_context_profile_mask").getAsInt()&1)!=0?GLFW.GLFW_OPENGL_CORE_PROFILE:GLFW.GLFW_OPENGL_COMPAT_PROFILE);else GLFW.glfwWindowHint(GLFW.GLFW_OPENGL_PROFILE,GLFW.GLFW_OPENGL_CORE_PROFILE);if(m.has("gl_context_flags")){int flags=m.get("gl_context_flags").getAsInt();GLFW.glfwWindowHint(GLFW.GLFW_OPENGL_FORWARD_COMPAT,(flags&1)!=0?1:0);if((flags&4)!=0)GLFW.glfwWindowHint(GLFW.GLFW_CONTEXT_ROBUSTNESS,m.has("gl_context_reset_strategy")&&m.get("gl_context_reset_strategy").getAsInt()==GL45.GL_LOSE_CONTEXT_ON_RESET?GLFW.GLFW_LOSE_CONTEXT_ON_RESET:GLFW.GLFW_NO_RESET_NOTIFICATION);GLFW.glfwWindowHint(GLFW.GLFW_CONTEXT_NO_ERROR,(flags&8)!=0?1:0);GLFW.glfwWindowHint(GLFW.GLFW_OPENGL_DEBUG_CONTEXT,(flags&2)!=0?1:0);}else GLFW.glfwWindowHint(GLFW.GLFW_OPENGL_FORWARD_COMPAT,1);if(m.has("gl_context_release_behavior")&&m.get("gl_context_release_behavior").getAsInt()>=0)GLFW.glfwWindowHint(GLFW.GLFW_CONTEXT_RELEASE_BEHAVIOR,m.get("gl_context_release_behavior").getAsInt()==0?GLFW.GLFW_RELEASE_BEHAVIOR_NONE:GLFW.GLFW_RELEASE_BEHAVIOR_FLUSH);GLFW.glfwWindowHint(GLFW.GLFW_CONTEXT_VERSION_MAJOR,Integer.parseInt(match.group(1)));GLFW.glfwWindowHint(GLFW.GLFW_CONTEXT_VERSION_MINOR,Integer.parseInt(match.group(2)));}
    static double percentile(double[] values,double q){var sorted=values.clone();Arrays.sort(sorted);return sorted[Math.max(0,(int)Math.ceil(q*sorted.length)-1)];}
    public static void main(String[] args)throws Exception{
        Path out=Path.of(System.getProperty("cmi.benchmark.output"));Files.createDirectories(out);int samples=Integer.getInteger("cmi.particle.samples",32);check(samples>=8&&samples<=1024,"sample count 8..1024");
        check(GLFW.glfwInit(),"GLFW");GLFW.glfwWindowHint(GLFW.GLFW_VISIBLE,0);contextForCapture(Path.of(System.getProperty("cmi.particle.capture")));long window=GLFW.glfwCreateWindow(32,32,"particle command replay",0,0);check(window!=0,"GL context");GLFW.glfwMakeContextCurrent(window);GL.createCapabilities();
        try(var replay=new Replay(Path.of(System.getProperty("cmi.particle.capture")))){
            for(int i=0;i<8;i++)replay.run();double[] gpu=new double[samples],cpu=new double[samples];
            for(int i=0;i<samples;i++){var timing=replay.run();gpu[i]=timing[0];cpu[i]=timing[1];}
            var result=new LinkedHashMap<String,Object>();result.put("scope","full recorded GL command stream; excludes unrecorded draws and CUDA; reset before each sample; not an equivalence or FPS claim");
            result.put("timing_ms",new double[]{Arrays.stream(gpu).average().orElseThrow(),Arrays.stream(cpu).average().orElseThrow()});
            result.put("distribution",Map.of("warmup",8,"samples",samples,"gpu_p50_ms",percentile(gpu,.5),"gpu_p95_ms",percentile(gpu,.95),"gpu_p99_ms",percentile(gpu,.99),"gpu_samples_ms",gpu,"cpu_submit_samples_ms",cpu));
            result.put("program_loading",replay.programLoading);result.put("actual_context_flags",GL11.glGetInteger(GL30.GL_CONTEXT_FLAGS));result.put("context_origin",replay.manifest.has("gl_context_flags")?"captured":"legacy core+forward recovered by binary compatibility probe");result.put("buffers",replay.hashes());
            Files.writeString(out.resolve("replay.json"),new GsonBuilder().setPrettyPrinting().create().toJson(result)+"\n");
        }finally{GLFW.glfwDestroyWindow(window);GLFW.glfwTerminate();}
    }
}
